pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Deploy a separate contract to execute reentrant attack
        address attacker = address(0x1234);
        vm.deal(attacker, 2 ether);
        vm.warp(1); // set block.timestamp to 1

        // First put 2 ether, unlock time = 0 (so already unlocked)
        vm.prank(attacker);
        c.Put{value: 2 ether}(0);

        // Now attacker calls Collect(1 ether) — in buggy version, reentrancy will allow another Collect call
        // In reference, reentrancy guard blocks it
        // We need to check the public MinSum variable after the call completes
        // The buggy version allows reentrancy which can drain and potentially change MinSum via overflow
        // Actually, to make a concrete difference, we check that after Collect, the reference returns normally but buggy reverts?
        // Let's do: call Collect(1 ether) — reference succeeds, buggy reverts because reentrancy leads to underflow?

        vm.startPrank(attacker);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", 1 ether));
        vm.stopPrank();

        // In reference, reentrancy guard blocks reentrancy so success is true
        // In buggy, reentrancy occurs, attacker calls Put(0) via fallback which adds balance, then Collect again leads to underflow revert
        assertTrue(success);
    }
}

