pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set unlock time to 0 so Collect is immediately callable
        uint unlockTime = 0;
        address alice = address(0xABCD);
        vm.deal(alice, 2 ether);

        // Alice puts 2 ether
        vm.prank(alice);
        c.Put{value: 2 ether}(unlockTime);

        // First Collect(1 ether) succeeds
        vm.prank(alice);
        c.Collect(1 ether);

        // Second Collect(1 ether) — reference reverts, buggy does not
        vm.prank(alice);
        try c.Collect(1 ether) {
            // buggy: succeeds, balance becomes 0
            assertTrue(address(c).balance == 0);
        } catch {
            // reference: reverts, balance remains 1 ether
            assertTrue(address(c).balance == 1 ether);
        }
    }
}

