        // Second Collect call: reference (with guard) should revert, buggy (without guard) should succeed
        bool secondSuccess;
        try c.Collect(1 ether) { secondSuccess = true; } catch { secondSuccess = false; }

        // In reference, second Collect reverts so contract balance stays 1 ether
        // In buggy, second Collect succeeds so balance becomes 0
        assertTrue(address(c).balance == 1 ether);
    }
}
